    ok=[]
    for t in ("customers","orders","ledger_entries"):
        try:
            cur.execute(f"SELECT COUNT(*) FROM {t}"); ok.append(f"{t}={cur.fetchone()[0]}")
        except Exception as e: ok.append(f"{t}=ERR")
    print(env, ok)
    con.close()
